#!/usr/bin/env node
// Keeps the sandbox's catalog (client/encounters/sandbox/catalog.js) in step
// with the encounters: every NPC a presentation written in modules draws
// (client/encounters/presentations.js, the way every new encounter is added)
// that the monster table has stats for and that has an attack clip is either
// in the curated catalog, or excluded there with a reason, or in the
// generated file client/encounters/sandbox/discovered.js, which this script
// writes. So a new encounter's monsters reach the sandbox without anyone
// writing an entry by hand; test/test-sandbox-catalog.mjs then fights each.
//
//   node tools/sandbox-catalog.mjs            list what is found and where it goes
//   node tools/sandbox-catalog.mjs --write    write discovered.js
//   node tools/sandbox-catalog.mjs --check    exit 1 when discovered.js is out of date
//
// Needs no game cache: the presentations and the monster table are modules.
// An entry's numbers come from the monster table (size, attack speed, the
// style its levels and bonuses favour) and its sequences from the render
// config that draws it; the entry says so in its comment.
import { register } from "node:module";
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { parseArgs } from "node:util";
import { discoverSandboxNpcs } from "./sandbox/discover.mjs";

const repo = path.resolve(import.meta.dirname, "..");
const target = path.join(repo, "client/encounters/sandbox/discovered.js");
const { values: opt } = parseArgs({ options: { write: { type: "boolean", default: false }, check: { type: "boolean", default: false } } });

register("./determinism/node-hooks.mjs", import.meta.url);
globalThis.self ??= globalThis;
globalThis.location ??= { pathname: "/" };

const client = (file) => import(new URL(`../client/${file}`, import.meta.url).href);
const { presentationBuilders } = await client("encounters/presentations.js");
const { encounterRegistry } = await client("encounters/registry.js");
const { monsterByNpcTypeId, getMonsterName } = await client("data/monsters.js");
const { curatedNpcCatalog, sandboxCatalogExclusions } = await client("encounters/sandbox/catalog.js");

// Each presentation, built with a stand-in for the scene classes (only its
// render config is read; no scene is made).
class StandInScene {}
const presentations = presentationBuilders.map((build) => build(StandInScene, () => 0, { presentationOf: () => undefined }));

// The sandbox's own presentations, and the test fixture the harness's hooks
// register (test/fixtures/register.mjs), are not read.
const fixtureKinds = new Set(["training_ground"]);
const { entries: discovered, report } = discoverSandboxNpcs({
  presentations,
  curatedIds: new Set(curatedNpcCatalog.map((entry) => entry.npcTypeId)),
  exclusions: sandboxCatalogExclusions,
  monsterOf: (npcTypeId) => monsterByNpcTypeId.get(npcTypeId),
  nameOf: getMonsterName,
  groupOf: (kind) => encounterRegistry.getDescriptorOfKindOrVariant(kind)?.displayName,
  skipKinds: (kind) => kind.startsWith("sandbox") || fixtureKinds.has(kind),
});

const text = `// Generated by tools/sandbox-catalog.mjs; do not edit. The NPCs that the
// encounters written in modules draw, that the monster table has stats for,
// and that the curated catalog (catalog.js) neither holds nor excludes. Each
// entry: size and attack speed from TABLE, the style its levels and bonuses
// favour (TABLE, inferred), a reach of 1 for melee and 10 otherwise
// (inferred), sequences from the render config of \`source\` (CACHE).
// Run \`node tools/sandbox-catalog.mjs --write\` after adding an encounter;
// test/test-sandbox-catalog.mjs fails while this file is out of date.
export const discoveredNpcCatalog = ${JSON.stringify(discovered, null, 2)};
`;

console.log(report.join("\n"));
console.log(`\n${discovered.length} discovered`);
const current = (() => {
  try {
    return readFileSync(target, "utf8");
  } catch {
    return "";
  }
})();
if (opt.write) {
  if (current !== text) writeFileSync(target, text);
  console.log(current === text ? "discovered.js is up to date" : "wrote " + path.relative(repo, target));
} else if (opt.check && current !== text) {
  console.log("discovered.js is out of date: run node tools/sandbox-catalog.mjs --write");
  process.exitCode = 1;
}
process.exit(process.exitCode ?? 0);
